        return None  # Inverse does not exist if b is zero
    x0, x1 = 0, 1
    y0, y1 = 1, 0

    while b != 0:
        quotient = a // b
        a, b = b, a % b
        x0, x1 = x1, x0 - quotient * x1
        y0, y1 = y1, y0 - quotient * y1

    if x0 < 0:
        return x0 + b
    return x0

