            for j in range(len(perm) - 1, i, -1):
                if perm[j] > perm[i]:
                    # Swap perm[i] with perm[j]
                    perm[i], perm[j] = perm[j], perm[i]
                    # Reverse the sub-list from i+1 to the end
                    perm[i+1:] = perm[i+1:][::-1]
                    return True
    # If the loop completes without finding a next permutation, return False
    return False

