        raise ValueError("Both 'n' and 'k' must be non-negative.")
    cooked_cigarettes = n
    burnt_butts = n

    while burnt_butts >= k:
        cooked_cigarettes += burnt_butts // k
        burnt_butts = burnt_butts % k + cooked_cigarettes

